Post Date: 2019-03-29T07:59:37Z
Current Date: April 4 2025
Title: defaultProps in HOC when use React.ComponentType<M>
Description: I have a problem of HOC .  when pass a component with a defaultProps to HOC, the props of component exposed to user become optional as the defaultProps is Partial. see example below

the property df1 and df2 is not optional after wrapper by HOC!

because 

```js
const TabRCT = Tab as React.ComponentType<Props & WithProps>
type DpProps = typeof TabRCT.defaultProps
type DpProps1 = typeof Tab.defaultProps
```
DpProps is Partial<Props & WithProps> | undefined
DpProps1 is DefaultTabProps


the complete example
 
```js
import * as React from 'react'

interface DefaultTabProps {
  df1: number,
  df2: string
}

interface Props extends DefaultTabProps {
  pp1?: number
  pp2: number
}

interface WithProps {
  wp: string
}

interface InjectProps {
  ij: number
}

class Tab extends React.Component<Props & WithProps, any> {
  static defaultProps: DefaultTabProps = {
    df1: 11,
    df2: '12'
  }
  render() {
    return <div />
  }
}


type Merge<M, T> = Pick<M, Exclude<keyof M, keyof T>> & T


// 希望M是处理后的 ，即最初M是Props，最后组件暴露出来的props是{...Props, ...DefaultProps }，而WithProps后暴露出来的还是Props，希望加上WithProps
function WithTest<M>(Cp: React.ComponentType<M & WithProps>) {
  return (props: Merge<M, typeof Cp.defaultProps> & InjectProps) => {
    let params = omit(props, ['ij']) as M
    let wp = (props.ij * 100) + '%'
    return <Cp {...params} wp={wp}/>
  }
}

const TabWith = WithTest(Tab)


function omit<T, K extends keyof T>(obj: T, keys: K[]) {
  const newObj: { [key in keyof OmitType<T, K>]?: T[key] } = {}

  return (Object.keys(obj) as (keyof OmitType<T, K>)[])
    .filter((curr: any) => !keys.includes(curr))
    .reduce((acc: { [key in keyof OmitType<T, K>]?: T[key] }, curr: (keyof OmitType<T, K>)) => (
      acc[curr] = obj[curr],
      acc
    ), newObj)
}
 

const obj = {
  A: <TabWith ij={12} pp2={1} /> 
}

```




